-- Breast Pathology AI Platform: metadata schema (contract v1)
-- PostgreSQL 16+ with the pgvector extension.
-- Conventions (see contracts/README.md):
--   * Entity IDs are UUIDv7, generated by the application (Guid.CreateVersion7() in .NET).
--   * No patient identifiers anywhere; cases are identified by a pseudonymous case_key.
--   * Coordinates are level-0 pixel coordinates; mpp is stored per slide.
--   * Every result records the model, pipeline and QC versions that produced it.
--   * Enum-like columns use text + CHECK so values match the OpenAPI and event schemas exactly.
-- EF Core migrations (L3.1) must produce this schema; this file is the reviewed reference.

CREATE EXTENSION IF NOT EXISTS vector;

-- ---------------------------------------------------------------------------
-- Cases and slides (written by ingestion)
-- ---------------------------------------------------------------------------

CREATE TABLE cases (
    id             uuid        PRIMARY KEY,
    case_key       text        NOT NULL UNIQUE,  -- pseudonymous, e.g. 'C16-TUMOR-001'
    site           text        NOT NULL,         -- source lab or dataset, e.g. 'camelyon16'
    specimen_type  text        NOT NULL
                   CHECK (specimen_type IN ('core_biopsy', 'excision', 'lymph_node', 'other')),
    received_at    timestamptz NOT NULL,
    created_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE slides (
    id                 uuid          PRIMARY KEY,
    case_id            uuid          NOT NULL REFERENCES cases (id) ON DELETE CASCADE,
    stain              text          NOT NULL
                       CHECK (stain IN ('he', 'ihc_er', 'ihc_pr', 'ihc_her2', 'ihc_ki67', 'other')),
    format             text,                       -- 'svs', 'tiff', 'ndpi', 'mrxs', 'dicom'
    scanner            text,                       -- vendor from metadata, e.g. 'aperio'
    mpp                numeric(8, 5) CHECK (mpp > 0),  -- NULL when the file doesn't say (US-10)
    width              integer       CHECK (width > 0),
    height             integer       CHECK (height > 0),
    file_size_bytes    bigint        CHECK (file_size_bytes > 0),
    object_key         text          NOT NULL UNIQUE,  -- raw/{slideId}
    checksum_sha256    char(64)      NOT NULL UNIQUE,  -- duplicate detection (US-13)
    status             text          NOT NULL
                       CHECK (status IN ('uploading', 'ingested', 'qc_passed', 'qc_failed',
                                         'tiled', 'processed', 'rejected', 'replaced')),
    replaces_slide_id  uuid          REFERENCES slides (id),  -- rescans (US-12)
    created_at         timestamptz   NOT NULL DEFAULT now(),
    updated_at         timestamptz   NOT NULL DEFAULT now()
);

-- "Slides of a case with status X" is the most common query (case page, rescan list).
CREATE INDEX ix_slides_case_status ON slides (case_id, status);

-- ---------------------------------------------------------------------------
-- Quality control (written by the QC worker)
-- ---------------------------------------------------------------------------

CREATE TABLE qc_results (
    id               uuid        PRIMARY KEY,
    slide_id         uuid        NOT NULL REFERENCES slides (id) ON DELETE CASCADE,
    qc_version       text        NOT NULL,
    verdict          text        NOT NULL CHECK (verdict IN ('pass', 'warn', 'fail')),
    reasons          text[]      NOT NULL DEFAULT '{}',  -- e.g. {'blur','pen_marks'}
    tissue_mask_key  text,                                -- qc/{slideId}/tissue-mask.png
    tissue_fraction  real        CHECK (tissue_fraction BETWEEN 0 AND 1),
    blur_score       real,
    fold_score       real,
    pen_score        real,
    stain_stats      jsonb,
    created_at       timestamptz NOT NULL DEFAULT now(),
    UNIQUE (slide_id, qc_version)  -- idempotent QC: one result per slide per QC version
);

-- ---------------------------------------------------------------------------
-- Tiles (written by the tiling worker)
-- Exception to the UUID rule: tens of thousands of rows per slide, identified
-- naturally by their position. Tile scores in Parquet use the same key.
-- ---------------------------------------------------------------------------

CREATE TABLE tiles (
    slide_id         uuid     NOT NULL REFERENCES slides (id) ON DELETE CASCADE,
    level            smallint NOT NULL CHECK (level >= 0),
    x                integer  NOT NULL CHECK (x >= 0),     -- level-0 pixel coordinates
    y                integer  NOT NULL CHECK (y >= 0),
    size             integer  NOT NULL CHECK (size > 0),   -- level-0 pixels per side
    tissue_fraction  real     NOT NULL CHECK (tissue_fraction BETWEEN 0 AND 1),
    PRIMARY KEY (slide_id, level, x, y, size)
);

-- ---------------------------------------------------------------------------
-- Models and inference (model registry, inference worker, aggregator)
-- ---------------------------------------------------------------------------

CREATE TABLE model_versions (
    id           uuid          PRIMARY KEY,
    name         text          NOT NULL,             -- e.g. 'tumor-resnet18'
    version      text          NOT NULL,             -- e.g. '1.0.0'
    task         text          NOT NULL
                 CHECK (task IN ('tumor_detection', 'grading', 'mitosis_detection')),
    onnx_key     text          NOT NULL,             -- models/{modelVersionId}/model.onnx
    model_card   jsonb         NOT NULL,
    metrics      jsonb         NOT NULL DEFAULT '{}',
    input_mpp    numeric(8, 5) NOT NULL CHECK (input_mpp > 0),
    tile_size    integer       NOT NULL CHECK (tile_size > 0),
    status       text          NOT NULL CHECK (status IN ('staging', 'production', 'retired')),
    created_at   timestamptz   NOT NULL DEFAULT now(),
    promoted_at  timestamptz,
    promoted_by  text,
    UNIQUE (name, version)
);

-- At most one production model per task (US-21).
CREATE UNIQUE INDEX ux_model_versions_production_per_task
    ON model_versions (task) WHERE status = 'production';

CREATE TABLE inference_runs (
    id                uuid        PRIMARY KEY,
    slide_id          uuid        NOT NULL REFERENCES slides (id) ON DELETE CASCADE,
    model_version_id  uuid        NOT NULL REFERENCES model_versions (id),
    qc_result_id      uuid        NOT NULL REFERENCES qc_results (id),  -- QC lineage
    pipeline_version  text        NOT NULL,
    status            text        NOT NULL
                      CHECK (status IN ('queued', 'running', 'completed', 'failed')),
    tile_scores_key   text,                       -- scores/{runId}.parquet
    error             text,
    queued_at         timestamptz NOT NULL DEFAULT now(),
    started_at        timestamptz,
    finished_at       timestamptz,
    UNIQUE (slide_id, model_version_id)  -- idempotent inference (US-23)
);

CREATE INDEX ix_inference_runs_model ON inference_runs (model_version_id);  -- US-22

CREATE TABLE slide_results (
    run_id          uuid        PRIMARY KEY REFERENCES inference_runs (id) ON DELETE CASCADE,
    label           text        NOT NULL,               -- e.g. 'tumor', 'normal', 'grade_2'
    score           real        NOT NULL CHECK (score BETWEEN 0 AND 1),
    uncertainty     real        NOT NULL CHECK (uncertainty >= 0),
    conformal_set   text[]      NOT NULL,               -- e.g. {'grade_2','grade_3'}
    heatmap_key     text,                               -- overlays/{runId}/tumor.png
    created_at      timestamptz NOT NULL DEFAULT now()
);

-- A pathologist's decision on a result (US-05). Results themselves are never edited.
CREATE TABLE pathologist_decisions (
    id          uuid        PRIMARY KEY,
    run_id      uuid        NOT NULL REFERENCES slide_results (run_id) ON DELETE CASCADE,
    decided_by  text        NOT NULL,
    decision    text        NOT NULL CHECK (decision IN ('agree', 'disagree')),
    comment     text,
    decided_at  timestamptz NOT NULL DEFAULT now(),
    CHECK (decision = 'agree' OR comment IS NOT NULL),  -- disagreeing needs a comment
    UNIQUE (run_id, decided_by)
);

-- ---------------------------------------------------------------------------
-- Reports and annotations
-- ---------------------------------------------------------------------------

CREATE TABLE reports (
    id                 uuid        PRIMARY KEY,
    case_id            uuid        NOT NULL REFERENCES cases (id) ON DELETE CASCADE,
    source             text        NOT NULL CHECK (source IN ('tcga', 'partner', 'manual')),
    raw_text_key       text        NOT NULL,   -- reports/{reportId}.txt
    extracted          jsonb,                  -- validated against the ReportStructured fields
    extractor_version  text,
    fhir_bundle_key    text,
    created_at         timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE annotations (
    id          uuid        PRIMARY KEY,
    slide_id    uuid        NOT NULL REFERENCES slides (id) ON DELETE CASCADE,
    author      text        NOT NULL,
    source      text        NOT NULL CHECK (source IN ('viewer', 'qupath', 'dataset')),
    label       text        NOT NULL,          -- e.g. 'tumor'
    geometry    jsonb       NOT NULL,          -- GeoJSON geometry in level-0 pixel coordinates
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX ix_annotations_slide ON annotations (slide_id);

-- ---------------------------------------------------------------------------
-- Similar-case search (Module 9). The vector size depends on the foundation
-- model chosen in L9.1; change it by migration then. HNSW index added in L9.2.
-- ---------------------------------------------------------------------------

CREATE TABLE region_embeddings (
    id          uuid         PRIMARY KEY,
    slide_id    uuid         NOT NULL REFERENCES slides (id) ON DELETE CASCADE,
    x           integer      NOT NULL,
    y           integer      NOT NULL,
    size        integer      NOT NULL,
    model_name  text         NOT NULL,
    embedding   vector(1024) NOT NULL
);

-- ---------------------------------------------------------------------------
-- Audit log (written by every service). Append-only.
-- Exception to the UUID rule: very many rows, only ever appended, ordered by id.
-- ---------------------------------------------------------------------------

CREATE TABLE audit_log (
    id           bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    actor        text        NOT NULL,          -- user or service name, never a patient
    action       text        NOT NULL
                 CHECK (action IN ('read', 'create', 'update', 'delete', 'login', 'export')),
    entity       text        NOT NULL,          -- e.g. 'slide'
    entity_id    text,
    occurred_at  timestamptz NOT NULL DEFAULT now(),
    details      jsonb
);

CREATE INDEX ix_audit_log_entity ON audit_log (entity, entity_id, occurred_at DESC);
CREATE INDEX ix_audit_log_actor ON audit_log (actor, occurred_at DESC);
